def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    last_me, last_opp = history[-1]
    opp_c = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
    opp_d = n - opp_c
    d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            d_streak += 1
        else:
            break
    c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            c_streak += 1
        else:
            break
    if opp_c == 0:
        return 'D'
    if d_streak >= 4:
        return 'D'
    if opp_d == 0 and n >= 12:
        return 'D'
    aCC = aCD = aDC = aDD = 0
    start = n - 30
    if start < 1:
        start = 1
    for i in range(start, n):
        pm = history[i - 1][0]
        om = history[i][1]
        if pm == 'C':
            if om == 'C':
                aCC += 1
            else:
                aCD += 1
        else:
            if om == 'C':
                aDC += 1
            else:
                aDD += 1
    totalD = aDD + aDC
    totalC = aCC + aCD
    retaliatory = False
    soft = False
    if totalD >= 5 and totalC >= 4:
        pDD = aDD / float(totalD)
        pCC = aCC / float(totalC)
        if pDD >= 0.75 and pCC <= 0.60:
            retaliatory = True
        if pDD <= 0.35 and pCC - pDD <= 0.30:
            soft = True
    if totalD >= 2 and aDC >= 2 and aDD == 0:
        soft = True
    if aDC >= 1 and aDD <= 1 and c_streak >= 3 and opp_d * 4 <= n:
        soft = True
    if retaliatory:
        soft = False
    if soft:
        return 'D'
    if retaliatory:
        if last_opp == 'D':
            if last_me == 'D':
                return 'C'
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            return 'D'
        return 'C'
    if last_opp == 'D':
        if last_me == 'D':
            return 'C'
        if n >= 2 and history[-2][0] == 'D':
            return 'C'
        return 'D'
    return 'C'
